CREATE OR REPLACE FUNCTION public.rue_position_enregistrer(p_noeud text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public','pg_temp' AS $fn$
DECLARE v_nom text; v_pj public.personnages_donnees%ROWTYPE; v_noeud public.rue_noeuds_serveur%ROWTYPE;
 v_depart text;
BEGIN
 v_nom:=public.mon_personnage();
 IF v_nom IS NULL THEN RETURN jsonb_build_object('ok',false,'raison','non_authentifie'); END IF;
 SELECT * INTO v_pj FROM public.personnages_donnees WHERE name=v_nom FOR UPDATE;
 IF NOT FOUND OR v_pj.est_emprisonne IS NOT NULL AND v_pj.est_emprisonne<>'null'::jsonb THEN
 RETURN jsonb_build_object('ok',false,'raison','personnage_indisponible'); END IF;
 IF EXISTS(SELECT 1 FROM public.police_interceptions WHERE personnage=v_nom AND expires_at>now()) THEN
 RETURN jsonb_build_object('ok',false,'raison','interception_en_cours'); END IF;
 SELECT * INTO v_noeud FROM public.rue_noeuds_serveur WHERE country=v_pj.country AND city=v_pj.current_city AND noeud=p_noeud;
 IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'raison','noeud_inconnu'); END IF;
 IF v_pj.current_building IS NOT NULL THEN
 IF NOT EXISTS(SELECT 1 FROM public.rue_sorties_batiments
 WHERE country=v_pj.country AND city=v_pj.current_city AND building=v_pj.current_building AND noeud=p_noeud) THEN
 RETURN jsonb_build_object('ok',false,'raison','sortie_invalide'); END IF;
 ELSIF v_pj.current_street IS NOT NULL AND v_pj.current_street<>p_noeud THEN
 IF NOT EXISTS(SELECT 1 FROM public.rue_noeuds_serveur
 WHERE country=v_pj.country AND city=v_pj.current_city AND noeud=v_pj.current_street
 AND p_noeud=ANY(voisins)) THEN RETURN jsonb_build_object('ok',false,'raison','trajet_invalide'); END IF;
 ELSIF v_pj.current_street IS NULL THEN
 v_depart:=CASE v_pj.current_city WHEN 'capitale' THEN 'luthecia-palais-presidentiel'
 WHEN 'ville_a' THEN 'psm-centre-multimodal' WHEN 'ville_b' THEN 'montrouge-vue-3' ELSE NULL END;
 IF p_noeud IS DISTINCT FROM v_depart THEN RETURN jsonb_build_object('ok',false,'raison','position_initiale_invalide'); END IF;
 END IF;
 UPDATE public.personnages_donnees SET current_building=NULL,current_room=NULL,current_street=p_noeud WHERE id=v_pj.id;
 UPDATE public.police_interceptions SET expires_at=now() WHERE personnage=v_nom AND expires_at>now();
 RETURN jsonb_build_object('ok',true,'noeud',p_noeud);
END;
$fn$;
REVOKE ALL ON FUNCTION public.rue_position_enregistrer(text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.rue_position_enregistrer(text) TO authenticated;

CREATE OR REPLACE FUNCTION public.police_detection_verifier(p_batiment text,p_piece text,p_rue text DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public','pg_temp' AS $detect$
DECLARE v_nom text; v_pj public.personnages_donnees%ROWTYPE; v_bat public.batiments_etat%ROWTYPE;
 v_agents jsonb; v_agent jsonb; v_count integer:=0; v_per numeric:=0; v_dis numeric; v_chance numeric;
 v_id text; v_last timestamptz;
BEGIN
 v_nom:=public.mon_personnage();
 IF v_nom IS NULL THEN RETURN jsonb_build_object('ok',false,'raison','non_authentifie'); END IF;
 SELECT * INTO v_pj FROM public.personnages_donnees WHERE name=v_nom FOR UPDATE;
 IF NOT FOUND OR v_pj.country<>'republic' OR v_pj.current_city IS NULL OR v_pj.est_emprisonne IS NOT NULL AND v_pj.est_emprisonne<>'null'::jsonb THEN
 RETURN jsonb_build_object('ok',false,'raison','joueur_indisponible'); END IF;
 IF (p_rue IS NOT NULL AND (v_pj.current_building IS NOT NULL OR v_pj.current_street IS DISTINCT FROM p_rue OR p_batiment IS NOT NULL OR p_piece IS NOT NULL))
 OR (p_rue IS NULL AND (p_batiment IS NULL OR p_piece IS NULL OR v_pj.current_building IS DISTINCT FROM p_batiment OR v_pj.current_room IS DISTINCT FROM p_piece)) THEN
 RETURN jsonb_build_object('ok',false,'raison','position_invalide'); END IF;
 IF NOT EXISTS(SELECT 1 FROM public.justice_recherches(v_nom) r WHERE r.country=v_pj.country) THEN
 RETURN jsonb_build_object('ok',false,'raison','non_recherche'); END IF;
 SELECT * INTO v_bat FROM public.batiments_etat WHERE country=v_pj.country AND city=v_pj.current_city
 AND building_id=CASE WHEN v_pj.current_city='capitale' THEN 'commissariat' ELSE 'commissariat-local' END;
 IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'raison','effectifs_absents'); END IF;
 v_agents:=v_bat.data::jsonb->'effectifsPolice'->'policiers';
 IF jsonb_typeof(v_agents) IS DISTINCT FROM 'array' THEN RETURN jsonb_build_object('ok',false,'raison','effectifs_invalides'); END IF;
 FOR v_agent IN SELECT value FROM jsonb_array_elements(v_agents) LOOP
 IF ((p_rue IS NOT NULL AND v_agent->>'rueNoeudId'=p_rue)
 OR (p_rue IS NULL AND v_agent->>'buildingId'=p_batiment AND v_agent->>'roomId'=p_piece)) AND coalesce((v_agent->>'pa')::integer,12)>0 THEN
 v_count:=v_count+1; v_per:=v_per+coalesce((v_agent->'stats'->>'PER')::numeric,12);
 END IF; END LOOP;
 IF v_count=0 THEN RETURN jsonb_build_object('ok',false,'raison','aucun_policier_present'); END IF;
 v_per:=v_per/v_count+(v_count-1)-CASE WHEN p_rue IS NOT NULL THEN 2 ELSE 0 END;
 SELECT rencontre INTO v_id FROM public.police_interceptions
 WHERE personnage=v_nom AND country=v_pj.country AND city=v_pj.current_city
 AND building IS NOT DISTINCT FROM p_batiment AND room IS NOT DISTINCT FROM p_piece
 AND street IS NOT DISTINCT FROM p_rue AND expires_at>now() LIMIT 1;
 IF v_id IS NOT NULL THEN RETURN jsonb_build_object('ok',true,'detecte',true,'rencontre',v_id); END IF;
 SELECT attempted_at INTO v_last FROM public.police_detection_attempts
 WHERE personnage=v_nom AND country=v_pj.country AND city=v_pj.current_city
 AND building=coalesce(p_batiment,'@rue') AND room=coalesce(p_piece,p_rue) FOR UPDATE;
 IF v_last IS NOT NULL AND v_last>now()-interval '2 minutes' THEN
 RETURN jsonb_build_object('ok',true,'detecte',false,'raison','detection_deja_tentee'); END IF;
 INSERT INTO public.police_detection_attempts(personnage,country,city,building,room,attempted_at)
 VALUES(v_nom,v_pj.country,v_pj.current_city,coalesce(p_batiment,'@rue'),coalesce(p_piece,p_rue),now())
 ON CONFLICT(personnage,country,city,building,room) DO UPDATE SET attempted_at=excluded.attempted_at;
 v_dis:=8+coalesce((v_pj.resources->>'dis')::numeric,0)/10;
 v_chance:=greatest(10,least(90,50+5*(v_dis-v_per)));
 IF random()*100 < v_chance THEN RETURN jsonb_build_object('ok',true,'detecte',false); END IF;
 v_id:='police-'||md5(v_nom||clock_timestamp()::text||random()::text);
 INSERT INTO public.police_interceptions(personnage,rencontre,country,city,building,room,street)
 VALUES(v_nom,v_id,v_pj.country,v_pj.current_city,p_batiment,p_piece,p_rue);
 RETURN jsonb_build_object('ok',true,'detecte',true,'rencontre',v_id);
END;
$detect$;
REVOKE ALL ON FUNCTION public.police_detection_verifier(text,text,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.police_detection_verifier(text,text,text) TO authenticated;

-- Primitive commune de résolution d'un coup : les caractéristiques et les PA sont
-- fournies par l'appelant autorisé ; les tirages et les dégâts restent au serveur.
-- Cette fonction ne modifie aucun personnage et ne remplace pas la validation
-- d'employeur, de présence et de droits de chaque ordre de combat.
CREATE OR REPLACE FUNCTION public.combat_coup_resoudre(
  p_comp_attaque numeric,
  p_comp_defense numeric,
  p_stat_defense numeric,
  p_bonus_arme integer,
  p_pa_cible integer
) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY INVOKER
SET search_path TO 'public', 'pg_temp'
AS $fn$
DECLARE
  v_taux integer;
  v_jet integer;
  v_degre text;
  v_pa integer;
BEGIN
  IF p_comp_attaque IS NULL OR p_comp_defense IS NULL OR
     p_stat_defense IS NULL OR p_pa_cible IS NULL OR
     p_pa_cible < 0 OR p_pa_cible > 100000 OR
     p_comp_attaque < 0 OR p_comp_defense < 0 OR p_stat_defense < 0 OR
     p_comp_attaque > 1000 OR p_comp_defense > 1000 OR p_stat_defense > 1000 OR
     coalesce(p_bonus_arme,0) NOT BETWEEN -100 AND 100 THEN
    RETURN jsonb_build_object('ok',false,'raison','parametres_invalides');
  END IF;
  v_taux := public.militaire_taux_combat(
    p_comp_attaque,p_comp_defense,p_stat_defense,coalesce(p_bonus_arme,0));
  v_jet := floor(random()*100)::integer+1;
  v_degre := public.militaire_degre_combat(v_taux,v_jet);
  v_pa := public.militaire_pa_restants(p_pa_cible,v_degre);
  RETURN jsonb_build_object('ok',true,'taux',v_taux,'jet',v_jet,
    'degre',v_degre,'pa_avant',p_pa_cible,'pa_apres',v_pa,
    'perte',p_pa_cible-v_pa,'neutralise',v_pa=0);
END;
$fn$;
REVOKE ALL ON FUNCTION public.combat_coup_resoudre(numeric,numeric,numeric,integer,integer) FROM PUBLIC, anon, authenticated;
COMMENT ON FUNCTION public.combat_coup_resoudre(numeric,numeric,numeric,integer,integer)
 IS 'Primitive de calcul interne réutilisant les taux, degrés et dégâts militaires. Ne confère aucune autorité ni modification de PA.';

CREATE OR REPLACE FUNCTION public.rue_position_lire()
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public','pg_temp' AS $fn$
DECLARE v_nom text; v_pj public.personnages_donnees%ROWTYPE;
BEGIN
 v_nom:=public.mon_personnage();
 IF v_nom IS NULL THEN RETURN jsonb_build_object('ok',false,'raison','non_authentifie'); END IF;
 SELECT * INTO v_pj FROM public.personnages_donnees WHERE name=v_nom;
 IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'raison','personnage_absent'); END IF;
 RETURN jsonb_build_object('ok',true,'country',v_pj.country,'city',v_pj.current_city,
 'building',v_pj.current_building,'room',v_pj.current_room,'street',v_pj.current_street);
END;
$fn$;
REVOKE ALL ON FUNCTION public.rue_position_lire() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.rue_position_lire() TO authenticated;
